def apply(inputs, premises):
    lengths = inputs["bag_lengths_inches"]
    widths = inputs["bag_widths_inches"]
    heights = inputs["bag_heights_inches"]
    weights = inputs["bag_weights_pounds"]
    personal_limits = premises["personal_item_limits"]
    carry_limits = premises["carry_on_limits"]
    checked_fees = premises["checked_bag_fees"]
    standard_limits = premises["standard_checked_limits"]
    overweight_bounds = premises["overweight_upper_bounds"]
    overweight_fees = premises["overweight_fees"]
    oversize_bounds = premises["oversize_upper_bounds"]
    oversize_fees = premises["oversize_fees"]
    personal_used = False
    carry_used = False
    checked_number = 0
    total = inputs["ticket_price"]
    for i in range(len(lengths)):
        is_personal = lengths[i] <= personal_limits[0] and widths[i] <= personal_limits[1] and heights[i] <= personal_limits[2]
        is_carry = lengths[i] <= carry_limits[0] and widths[i] <= carry_limits[1] and heights[i] <= carry_limits[2]
        if is_personal and not personal_used:
            personal_used = True
        elif is_carry and not carry_used:
            carry_used = True
        else:
            checked_number = checked_number + 1
            if checked_number <= len(checked_fees):
                total = total + checked_fees[checked_number - 1]
            else:
                total = total + checked_fees[len(checked_fees) - 1]
            size = lengths[i] + widths[i] + heights[i]
            overweight = 0
            if weights[i] > standard_limits[1]:
                for j in range(len(overweight_bounds)):
                    if weights[i] <= overweight_bounds[j]:
                        overweight = overweight_fees[j]
                        break
            oversize = 0
            if size > standard_limits[0]:
                for j in range(len(oversize_bounds)):
                    if size <= oversize_bounds[j]:
                        oversize = oversize_fees[j]
                        break
            if premises["use_higher_excess_fee"]:
                total = total + max(overweight, oversize)
            else:
                total = total + overweight + oversize
    return {"answer": int(total)}

def apply(inputs, premises):
    descriptions = inputs["asset_descriptions"]
    values = inputs["asset_values"]
    asset_types = inputs["asset_types"]
    citations = premises["rule_citations"]
    rule_types = premises["rule_asset_types"]
    caps = premises["rule_caps"]
    records = {}
    for i in range(len(descriptions)):
        claims = []
        for j in range(len(citations)):
            applicable = rule_types[j] == "any" or rule_types[j] == asset_types[i]
            if applicable:
                claims = claims + [{"citation": citations[j], "claim_value": min(values[i], caps[j])}]
        records[descriptions[i]] = claims
    return {"claim_records": records}

